def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    # --- Score tracking (own score only needed; opponent for reference) ---
    my_score = 0
    opp_score = 0
    for a, b in history:
        if a == 'C':
            if b == 'C':
                my_score += 3
                opp_score += 3
            else:
                opp_score += 5
        else:
            if b == 'C':
                my_score += 5
            else:
                my_score += 1
                opp_score += 1

    # --- Basic statistics ---
    opp_c = 0
    my_c = 0
    for a, b in history:
        if b == 'C':
            opp_c += 1
        if a == 'C':
            my_c += 1
    opp_d = n - opp_c
    my_d = n - my_c
    opp_rate = opp_c / n
    my_rate = my_c / n

    # --- Recent window statistics ---
    w = 10 if n >= 10 else n
    recent = history[-w:]
    r_opp_c = 0
    r_my_c = 0
    for a, b in recent:
        if b == 'C':
            r_opp_c += 1
        if a == 'C':
            r_my_c += 1
    r_opp_rate = r_opp_c / w
    r_my_rate = r_my_c / w

    # Narrower recent window (4)
    w2 = 4 if n >= 4 else n
    recent2 = history[-w2:]
    r2_opp_c = 0
    for a, b in recent2:
        if b == 'C':
            r2_opp_c += 1
    r2_opp_rate = r2_opp_c / w2

    last_me, last_op = history[-1]

    # --- Streaks ---
    opp_def_streak = 0
    for a, b in reversed(history):
        if b == 'D':
            opp_def_streak += 1
        else:
            break
    opp_c_streak = 0
    for a, b in reversed(history):
        if b == 'C':
            opp_c_streak += 1
        else:
            break
    mutual_c_streak = 0
    for a, b in reversed(history):
        if a == 'C' and b == 'C':
            mutual_c_streak += 1
        else:
            break

    rounds_left = 100 - n

    # --- Opening ---
    if n < 3:
        return 'C'

    # --- Endgame: aggressive exploitation of known cooperators ---
    if rounds_left <= 1:
        # Always defect on the very last round for DC payoff
        return 'D'
    if rounds_left <= 3:
        if r_opp_rate >= 0.5 and last_op == 'C':
            return 'D'
        if opp_rate >= 0.6 and last_op == 'C':
            return 'D'
        if last_op == 'D':
            return 'D'
        return 'C'
    if rounds_left <= 6:
        if opp_rate >= 0.7:
            # Mostly cooperative opponent: defecting now grabs 5s
            if r_opp_rate >= 0.5:
                return 'D'
            return 'C'
        if opp_rate <= 0.35 or r_opp_rate <= 0.3:
            return 'D'
        if last_op == 'D':
            return 'D'
        if mutual_c_streak >= 3:
            # Break cooperation for last-minute gains only if very safe
            if rng.random() < 0.4:
                return 'D'
            return 'C'
        return 'C'

    # --- Heavy defector: punish ---
    if opp_rate <= 0.2 and n >= 6:
        # Rarely forgive to test
        if rng.random() < 0.05:
            return 'C'
        return 'D'

    # --- Mostly defecting opponent: defect, with rare probes ---
    if opp_rate <= 0.35 and n >= 5:
        if rng.random() < 0.08:
            return 'C'
        return 'D'

    # --- Long mutual cooperation: keep it, but exploit rarely ---
    if mutual_c_streak >= 12:
        # Very long cooperation. Rare defection for extra points.
        if rng.random() < 0.07:
            return 'D'
        return 'C'

    # --- Opponent heavily cooperative: cooperate but probe intelligently ---
    if opp_rate >= 0.85 and r_opp_rate >= 0.7:
        # Rare probe if we've been very cooperative
        if my_rate >= 0.85 and rng.random() < 0.05:
            return 'D'
        return 'C'

    # --- Classic tit-for-tat with smart forgiveness ---
    if last_op == 'D':
        # If opponent's overall rate is high, likely an error/one-off; forgive
        if opp_rate >= 0.75 and opp_def_streak <= 1:
            return 'C'
        # If short defection streak and recent coop is high, forgive with prob
        if opp_def_streak == 1 and r_opp_rate >= 0.6:
            if rng.random() < 0.5:
                return 'C'
            return 'D'
        # If opponent defecting repeatedly, punish strongly
        if opp_def_streak >= 3:
            return 'D'
        if opp_def_streak == 2:
            # Probe for cooperation occasionally to break DD loops
            if rng.random() < 0.15:
                return 'C'
            return 'D'
        # Single defection from a mixed opponent: retaliate once
        return 'D'
    else:
        # Opponent cooperated. Return to cooperation unless we want to exploit.
        # If we just defected and opponent still cooperated, definitely cooperate.
        if last_me == 'D':
            return 'C'
        # Occasionally probe a persistently generous opponent
        if opp_c_streak >= 5 and r_opp_rate >= 0.8 and rng.random() < 0.06:
            return 'D'
        return 'C'
